head.script:
scwin.trigger1_onclick = function(e) {
    fchart.setPlotColor(["d9b4e5", "c68dd8", "9f41bd", "803598", "ff6301"]);
    fchart.setChartAttribute(options);
    fchart.setJSONData(datasource);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");	
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('trigger1').getValue() == 'colorChange'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('fchart').options.plotColor == '2ec6c8,b5a1dd,5ab0ee,f4984e,d77a80,90bddc,fe5d55,b5dc59,9ea7b3,00ba84,878bb6,757a85'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('fchart').options.plotColor != '2ec6c8,b5a1dd,5ab0ee,f4984e,d77a80,90bddc,fe5d55,b5dc59,9ea7b3,00ba84,878bb6,757a85'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('fchart').options.plotColor == 'd9b4e5,c68dd8,9f41bd,803598,ff6301'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

